import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CU_ytobU.js";var i=JSON.parse(`{"title":"Class: CommandChainedSubcommand","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: CommandChainedSubcommand"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/protocol/classes/CommandChainedSubcommand"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/protocol/classes/CommandChainedSubcommand"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/protocol/src"}},"headers":[],"relativePath":"api/@jsprismarine/protocol/classes/CommandChainedSubcommand.md","filePath":"api/@jsprismarine/protocol/classes/CommandChainedSubcommand.md","lastUpdated":1794310385000}`),a={name:`api/@jsprismarine/protocol/classes/CommandChainedSubcommand.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/protocol</a> / CommandChainedSubcommand</p><h1 id="class-commandchainedsubcommand" tabindex="-1">Class: CommandChainedSubcommand <a class="header-anchor" href="#class-commandchainedsubcommand" aria-label="Permalink to “Class: CommandChainedSubcommand”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf74b8c20010a451ae6cbb07ac9ef06ec9c735f0/packages/protocol/src/wire/structures/CommandChainedSubcommand.ts#L14" target="_blank" rel="noreferrer">protocol/src/wire/structures/CommandChainedSubcommand.ts:14</a></p><p>One <code>Chained Subcommand Data</code> table of <code>AvailableCommandsPacket</code>.</p><p>A chained subcommand is how Bedrock expresses <code>/execute</code>, and nothing else: an overload whose tail is &quot;and then another subcommand&quot; ends in a parameter pointing at one of these tables, and the table lists the keywords that may follow. Mojang added the four fields together at protocol 594 (1.20.10) and uses a single table, <code>EXECUTECHAINEDOPTION_0</code>, in 17 places across its own command set.</p><p>The table is numbered in its own index space, separate from both the hard and the soft enum tables, even though a parameter refers to it with the same <code>Enum</code> and <code>Valid</code> flags. The <code>EnumAsChainedCommand</code> option bit is what tells a client which space the index is in.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new CommandChainedSubcommand</strong>(): <code>CommandChainedSubcommand</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>CommandChainedSubcommand</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf74b8c20010a451ae6cbb07ac9ef06ec9c735f0/packages/protocol/src/wire/structures/CommandChainedSubcommand.ts#L16" target="_blank" rel="noreferrer">protocol/src/wire/structures/CommandChainedSubcommand.ts:16</a></p><p>The table&#39;s name, which Mojang spells <code>EXECUTECHAINEDOPTION_0</code>.</p><hr><h3 id="values" tabindex="-1">values <a class="header-anchor" href="#values" aria-label="Permalink to “values”">​</a></h3><blockquote><p><strong>values</strong>: <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/cf74b8c20010a451ae6cbb07ac9ef06ec9c735f0/packages/protocol/src/wire/structures/CommandChainedSubcommand.ts#L19" target="_blank" rel="noreferrer">protocol/src/wire/structures/CommandChainedSubcommand.ts:19</a></p><p>The subcommand keywords that may follow.</p>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};